// SPDX-License-Identifier: MIT
pragma solidity ^0.8.20;

// AUTO-GENERATED by assets/build.mjs from assets/source/<group>/<trait>.svg.
// DO NOT EDIT BY HAND. Regenerate with `pnpm build:assets`.
//
// Each function returns the minified inner SVG fragment (no <svg> wrapper) for
// a single 32x32 primitive. The Renderer concatenates them inside one outer
// <svg viewBox="0 0 32 32"> in strict layer order:
//
//   background -> skin -> underwear -> hand -> mouth -> head
//
// 1/1 tokens render as a single full-frame primitive from `1of1` and skip the
// layered stack entirely (deterministically assigned at mint, mutually
// exclusive with every other trait).
//
// Naming: <group><Trait> camelCase. Group = folder (1of1 → `oneOfOne` in
// identifiers), Trait = file basename.
//
// Heavy groups (skin, head, hand) live in dedicated `Assets<Group>`
// libraries with `public` functions to keep GraveShift under the EIP-170
// runtime size limit. Light groups (background, mouth, underwear) stay inlined
// here. The wrappers below preserve the historical `Assets.<fn>()` call
// surface so the Renderer / InkMath don't need to import each sub-library.
//
// Trait taxonomy (SolidityEng: lock IDs against this list):
// 1of1        gainable:    state-only: austronaut, dracula, master, superman
// background  live (gainable IDs): 2=#5cb8e7, 3=#ffbb53, 5=#63197c, 6=#ea6874
//             tombstone-reserved:  1=#282828
//             zombie-reserved:     4=#33357c
// hand        gainable: banana, gun, harp, sword, torch, wand
// head        gainable: UFO, clown, crown, halo, hood, wiz_hat
// mouth       gainable: cigar, glasses, spit
// skin        gainable: alien, ape, zombie   state-only: base, tombstone
// underwear   gainable: underwear-1, underwear-2

import {AssetsHand} from "assets/AssetsHand.sol";
import {AssetsHead} from "assets/AssetsHead.sol";
import {AssetsOneOfOneA} from "assets/AssetsOneOfOneA.sol";
import {AssetsOneOfOneB} from "assets/AssetsOneOfOneB.sol";
import {AssetsSkin} from "assets/AssetsSkin.sol";

library Assets {
    /// @dev background/01-tombstone - 64 bytes
    function background01Tombstone() internal pure returns (string memory) {
        return '<g fill="#282828"><rect x="0" y="0" width="32" height="32"/></g>';
    }

    /// @dev background/02-live-blue - 64 bytes
    function background02LiveBlue() internal pure returns (string memory) {
        return '<g fill="#5cb8e7"><rect x="0" y="0" width="32" height="32"/></g>';
    }

    /// @dev background/03-live-orange - 64 bytes
    function background03LiveOrange() internal pure returns (string memory) {
        return '<g fill="#ffbb53"><rect x="0" y="0" width="32" height="32"/></g>';
    }

    /// @dev background/04-zombie - 64 bytes
    function background04Zombie() internal pure returns (string memory) {
        return '<g fill="#33357c"><rect x="0" y="0" width="32" height="32"/></g>';
    }

    /// @dev background/05-live-purple - 64 bytes
    function background05LivePurple() internal pure returns (string memory) {
        return '<g fill="#63197c"><rect x="0" y="0" width="32" height="32"/></g>';
    }

    /// @dev background/06-live-red - 64 bytes
    function background06LiveRed() internal pure returns (string memory) {
        return '<g fill="#ea6874"><rect x="0" y="0" width="32" height="32"/></g>';
    }

    /// @dev mouth/cigar - 314 bytes
    function mouthCigar() internal pure returns (string memory) {
        return '<g fill="#7c7c7c"><rect x="20" y="9" width="2" height="1"/><rect x="21" y="8" width="3" height="1"/><rect x="22" y="7" width="3" height="1"/><rect x="23" y="6" width="2" height="1"/></g><g fill="#ffffff"><rect x="17" y="10" width="2" height="1"/></g><g fill="#f45700"><rect x="19" y="10" width="1" height="1"/></g>';
    }

    /// @dev mouth/glasses - 146 bytes
    function mouthGlasses() internal pure returns (string memory) {
        return '<g fill="#000000"><rect x="10" y="7" width="11" height="1"/><rect x="12" y="8" width="3" height="1"/><rect x="17" y="8" width="3" height="1"/></g>';
    }

    /// @dev mouth/spit - 106 bytes
    function mouthSpit() internal pure returns (string memory) {
        return '<g fill="#5cb8e7"><rect x="15" y="11" width="2" height="1"/><rect x="16" y="12" width="1" height="1"/></g>';
    }

